window.NABH_DATA = {"chapters": {"AAC": {"code": "AAC", "name": "Access, Assessment and Continuity of Care", "standards": [{"code": "AAC.1", "text": "The organisation defines and displays the healthcare services that it provides.", "elements": [{"letter": "a", "category": "Commitment", "text": "The healthcare services being provided are defined and are in consonance with the needs of the community.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Each defined clinical service shall have diagnostic and treatment services with suitably qualified personnel who provide out-patient, in-patient, daycare and emergency cover.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Scope of the clinical services of each department is defined.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "The organisation’s defined clinical services are prominently displayed. The organisation has a well-defined registration and admission", "sop": false}]}, {"code": "AAC.2", "text": "The organisation has a well-defined registration and admission process.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation uses written guidance for registering and admitting patients.", "sop": true}, {"letter": "b", "category": "CORE", "text": "A unique identification number is generated at the end of the registration.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Patients are accepted only if the organisation can provide the required service.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The written guidance also addresses managing patients during non-availability of beds.", "sop": true}, {"letter": "e", "category": "Achievement", "text": "Access to the healthcare services in the organisation is prioritised according to the clinical needs of the patient. There is an appropriate mechanism for transfer (in and out) or referral", "sop": true}]}, {"code": "AAC.3", "text": "There is an appropriate mechanism for transfer (in and out) or referral of patients.", "elements": [{"letter": "a", "category": "Commitment", "text": "Transfer-in of patients to the organisation is done appropriately.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Transfer-out / referral of patients to another facility is done appropriately.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "During transfer or referral, accompanying staff are appropriate to the clinical condition of the patient.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation gives a summary of the patient’s condition and the treatment given. Patients cared for by the organisation undergo an established initial", "sop": false}]}, {"code": "AAC.4", "text": "Patients cared for by the organisation undergo an established initial assessment.", "elements": [{"letter": "a", "category": "CORE", "text": "The initial assessment of the out-patients, daycare, in-patients and emergency patients is done in a standardised manner.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The initial assessment is performed by qualified personnel.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The initial assessment is performed within a time frame based on the needs of the patient.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Initial assessment of daycare and in-patients includes nursing assessment, which is done at the time of admission and documented.", "sop": false}, {"letter": "e", "category": "CORE", "text": "The initial assessment for in-patients results in a documented care plan.", "sop": false}, {"letter": "f", "category": "Achievement", "text": "The care plan is countersigned by the clinician in-charge of the patient within 24 hours.", "sop": false}, {"letter": "g", "category": "Excellence", "text": "The care plan includes the identification of special needs regarding care following discharge.", "sop": false}]}, {"code": "AAC.5", "text": "Patients cared for by the organisation undergo a regular re-assessment.", "elements": [{"letter": "a", "category": "CORE", "text": "Patients are re-assessed at appropriate intervals to determine their response to treatment and to plan further treatment or discharge.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Out-patients are informed of their next follow-up, where appropriate.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "For in-patients during re-assessment, the care plan is monitored and modified, where found necessary.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Staff involved in direct clinical care document re-assessments.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation lays down guidelines and implements processes to identify early warning signs of change or deterioration in clinical conditions for initiating prompt intervention. Laboratory services are provided as per the scope of services of the", "sop": true}]}, {"code": "AAC.6", "text": "Laboratory services are provided as per the scope of services of the organisation.", "elements": [{"letter": "a", "category": "Commitment", "text": "Scope of the laboratory services is commensurate to the services provided by the organisation.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The infrastructure (physical and equipment) is adequate to provide the defined scope of services.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Human resource is adequate to provide the defined scope of services.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Qualified and trained personnel perform and supervise the investigations and report the results.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Requisition for tests, collection, identification, handling, safe transportation, processing and disposal of a specimen is performed according to written guidance.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "Laboratory results are available within a defined time frame.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "Critical results are intimated to the person concerned at the earliest.", "sop": true}, {"letter": "h", "category": "Commitment", "text": "Results are reported in a standardised manner.", "sop": false}, {"letter": "i", "category": "Achievement", "text": "There is a mechanism to address the recall / amendment of reports whenever applicable.", "sop": true}, {"letter": "j", "category": "Commitment", "text": "Laboratory tests not available in the organisation are outsourced to the organisation(s) based on their quality assurance system. There is an established laboratory quality assurance and safety", "sop": true}]}, {"code": "AAC.7", "text": "There is an established laboratory quality assurance and safety programme.", "elements": [{"letter": "a", "category": "Commitment", "text": "The laboratory quality assurance programme is implemented.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The programme ensures the quality of test results through internal quality control.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Laboratory participates in proficiency testing / external quality assurance scheme.", "sop": false}, {"letter": "d", "category": "Excellence", "text": "The programme addresses the clinico-pathological meeting(s).", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The laboratory safety programme is implemented.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "Laboratory personnel are appropriately trained in safe practices.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Laboratory personnel are provided with appropriate safety measures. Imaging services are provided as per the scope of services of the", "sop": false}]}, {"code": "AAC.8", "text": "Imaging services are provided as per the scope of services of the organisation.", "elements": [{"letter": "a", "category": "CORE", "text": "Imaging services comply with legal and other requirements.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Scope of the imaging services is commensurate to the services provided by the organisation.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The infrastructure (physical and equipment) and human resources are adequate to provide for its defined scope of services.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Qualified and trained personnel perform, supervise and interpret the investigations.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Imaging results are available within a defined time frame.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "Critical results are intimated immediately to the personnel concerned.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "Results are reported in a standardised manner.", "sop": false}, {"letter": "h", "category": "Achievement", "text": "There is a mechanism to address the recall / amendment of reports whenever applicable.", "sop": true}, {"letter": "i", "category": "Commitment", "text": "Imaging tests not available in the organisation are outsourced to the organisation(s) based on their quality assurance system. There is an established quality assurance and safety programme for", "sop": false}]}, {"code": "AAC.9", "text": "There is an established quality assurance and safety programme for imaging services.", "elements": [{"letter": "a", "category": "Commitment", "text": "The quality assurance programme for imaging services is implemented.", "sop": true}, {"letter": "b", "category": "Achievement", "text": "A system is in place to ensure the appropriateness of the investigations and procedures for the clinical indication.", "sop": false}, {"letter": "c", "category": "Achievement", "text": "The programme addresses periodic internal / external peer review of imaging results using appropriate sampling.", "sop": false}, {"letter": "d", "category": "Excellence", "text": "The programme addresses the clinico-radiological meeting(s).", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The programme includes the documentation of corrective and preventive actions.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The radiation-safety programme is implemented.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "Patients are appropriately screened for safety / risk before imaging.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Imaging personnel and patients use appropriate radiation-safety and monitoring devices where applicable.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "Radiation-safety and monitoring devices are periodically tested, and results are documented.", "sop": true}, {"letter": "j", "category": "Commitment", "text": "Imaging and ancillary personnel are trained in imaging safety practices and radiation-safety measures.", "sop": false}, {"letter": "k", "category": "Commitment", "text": "Imaging signage is prominently displayed in all appropriate locations.", "sop": false}]}, {"code": "AAC.10", "text": "Patient care is continuous and multi-disciplinary.", "elements": [{"letter": "a", "category": "Commitment", "text": "During all phases of care, there is a qualified individual identified as responsible for the patient’s care.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Patient care is coordinated in all care settings within the organisation.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Information about the patient’s care and response to treatment is shared among medical, nursing and other care providers.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation implements standardised hand-over communication during each staffing shift, between shifts and during transfers between units / departments.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Patient transfer within the organisation is done safely.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Referral of patients to other departments / specialities follow written guidance.", "sop": true}, {"letter": "g", "category": "Achievement", "text": "The organisation ensures predictable service delivery by adhering to defined timelines and informs the patient / family and / or caregiver whenever there is a change in schedule.", "sop": false}, {"letter": "h", "category": "Excellence", "text": "The organisation has a mechanism in place to monitor whether an adequate clinical intervention has taken place in response to a critical value alert. The preventive and promotive health services are provided in a safe,", "sop": false}]}, {"code": "AAC.11", "text": "The preventive and promotive health services are provided in a safe, collaborative and consistent manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Written guidance governs the implementation of preventive and promotive care as per the scope of services.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Organisation shall define evidenced based and contextual age-appropriate screening for non-communicable diseases.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Mental health screening and appropriate intervention is advised for patients wherever applicable.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Evidence based and contextual paediatric and adult immunisation shall be advised wherever applicable.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "A multi-disciplinary approach is adopted in imparting health education on life-style modifications.", "sop": false}]}, {"code": "AAC.12", "text": "The organisation has an established discharge process.", "elements": [{"letter": "a", "category": "Commitment", "text": "The patient’s discharge process is planned in consultation with the patient and / or family.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The discharge process is coordinated among various departments and agencies involved (including medico-legal and absconded cases).", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Written guidance governs the discharge of patients leaving against medical advice.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "A discharge summary is given to all the patients leaving the organisation including patients leaving against medical advice.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The organisation adheres to planned discharge.", "sop": false}, {"letter": "f", "category": "Achievement", "text": "The care shall be provided by expanding access to health practices through domiciliary visits, wherever applicable.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The organisation monitors the discharge time, sets appropriate benchmarks and makes continual improvement.", "sop": false}]}, {"code": "AAC.13", "text": "The organisation defines the content of the discharge summary. *This implies that the objective element requires documentation", "elements": [{"letter": "a", "category": "Commitment", "text": "A discharge summary is provided to the patients at the time of discharge.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Discharge summary has a standardised content.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Discharge summary contains follow-up advice, medication and other instructions in an understandable manner.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Discharge summary incorporates instructions about when and how to obtain urgent care.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "In case of death, the summary of the case also includes the cause of death.", "sop": false}]}]}, "COP": {"code": "COP", "name": "Care of Patients", "standards": [{"code": "COP.1", "text": "Uniform care to patients is provided in all settings of the organisation and is guided by written guidance.*", "elements": [{"letter": "a", "category": "Commitment", "text": "Uniform care is provided to patients following written guidance .", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation has a uniform process for identification of patients and uses at least two identifiers.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation implements evidence-based clinical practice guidelines and / or clinical protocols to guide uniform patient care.", "sop": false}, {"letter": "d", "category": "Excellence", "text": "Clinical care pathways are developed, consistently followed across all settings of care, and reviewed periodically.", "sop": false}, {"letter": "e", "category": "Excellence", "text": "Multi-disciplinary and multi-speciality care, where appropriate, is planned based on best clinical practices / clinical practice guidelines and delivered in a uniform manner across the organisation.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Telemedicine facility is provided safely and securely based on written guidance. Emergency services are provided in accordance with written", "sop": true}]}, {"code": "COP.2", "text": "Emergency services are provided in accordance with written guidance, applicable laws and regulations.", "elements": [{"letter": "a", "category": "Commitment", "text": "There shall be an identified area in the organisation which is easily accessible to receive and manage emergency patients, with adequate and appropriate resources.", "sop": false}, {"letter": "b", "category": "Achievement", "text": "Prevention of patient over-crowding is planned and crowd management measures are implemented.", "sop": false}, {"letter": "c", "category": "CORE", "text": "Emergency care is provided in consonance with statutory requirements including medico-legal cases and as per written guidance.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Initiation of appropriate care is guided by a system of triage.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Patients waiting in the emergency are re-assessed as appropriate for the change in status.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Admission, discharge to home or transfer to another organisation is documented.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "In case of discharge to home or transfer to another organisation, a discharge / transfer note shall be given to the patient.", "sop": false}, {"letter": "h", "category": "Achievement", "text": "The organisation shall implement a quality assurance programme.", "sop": true}, {"letter": "i", "category": "Commitment", "text": "The organisation has systems in place for the management of patients found dead on arrival and patients who die within a few minutes of arrival. Ambulance services ensure safe patient transportation with", "sop": true}]}, {"code": "COP.3", "text": "Ambulance services ensure safe patient transportation with appropriate care. The organisation plans and implements mechanisms for the care of patients during community emergencies, epidemics and other disasters.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation has access to ambulance services commensurate with the scope of the services provided by it.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "There are adequate access and space for the ambulance(s).", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The ambulance(s) is fit for purpose and is appropriately equipped.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The ambulance(s) is operated by trained personnel.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The ambulance(s) is checked daily for functioning status, medical equipment, emergency medications and consumables.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The ambulance(s) has a proper communication system.", "sop": true}, {"letter": "g", "category": "Achievement", "text": "The emergency department identifies opportunities to initiate treatment at the earliest when the patient is in transit to the organisation. The organisation plans and implements mechanisms for the care of", "sop": false}]}, {"code": "COP.4", "text": "The organisation plans and implements mechanisms for the care of patients during community emergencies, epidemics and other disasters.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation identifies potential community emergencies, epidemics and other disasters.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation manages community emergencies, epidemics and other disasters as per a documented plan.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Provision is made for availability of medical supplies, equipment and materials during such emergencies.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The plan is tested at least twice a year. Cardio-pulmonary resuscitation services are provided uniformly", "sop": false}]}, {"code": "COP.5", "text": "Cardio-pulmonary resuscitation services are provided uniformly across the organisation.", "elements": [{"letter": "a", "category": "Commitment", "text": "Cardio-pulmonary resuscitation services are available and provided to patients at all times.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "During cardio-pulmonary resuscitation, assigned roles and responsibilities are complied with.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Medical equipment and medications for use during cardio-pulmonary resuscitation are available in various areas of the organisation.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The events during cardio-pulmonary resuscitation are recorded.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "A multi-disciplinary committee does a post-event analysis of cardio-pulmonary resuscitations.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Corrective and preventive measures are taken based on the post-event analysis. Nursing care is provided to patients in the organisation in consonance", "sop": false}]}, {"code": "COP.6", "text": "Nursing care is provided to patients in the organisation in consonance with clinical protocols.", "elements": [{"letter": "a", "category": "Commitment", "text": "Nursing care is provided to patients in accordance with written guidance.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Assignment of patient care is done as per good clinical / nursing practice.", "sop": false}, {"letter": "c", "category": "Achievement", "text": "The organisation implements acuity-based staffing to improve patient outcomes.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Nursing care is aligned and integrated with overall patient care which is documented.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Nurses are provided with the appropriate and adequate equipment for providing safe and efficient nursing care.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Nurses are empowered to make patient care decisions within their scope of practice.", "sop": false}]}, {"code": "COP.7", "text": "Clinical procedures are performed safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Clinical procedures are performed based on the clinical needs of the patient.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Performance of various clinical procedures is based on written guidance and done in a safe manner.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Qualified personnel order, plan, perform and assist in performing procedures.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Care is taken to prevent adverse events like a wrong patient, wrong procedure and wrong site.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Informed consent is taken by the personnel performing the procedure, where applicable.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Patients are appropriately monitored during and after the procedure.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Procedures are documented accurately in the patient record. Transfusion services are provided as per the scope of services of the", "sop": false}]}, {"code": "COP.8", "text": "Transfusion services are provided as per the scope of services of the organisation, safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Scope of transfusion services is commensurate with the services provided by the organisation.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation shall establish and implement processes for blood / component collection, testing, storage and distribution under written guidance.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Blood and components are stored safely from the time of collection till transfusion.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation ensures safe and rational use of blood and blood components.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Blood / blood components are available for use in emergency and routine situations within a defined time-frame.", "sop": true}, {"letter": "f", "category": "Achievement", "text": "The organisation shall ensure that post-transfusion form is collected, reactions if any identified and are analysed for preventive and corrective actions.", "sop": true}, {"letter": "g", "category": "Achievement", "text": "The organisation shall implement a quality assurance programme. The organisation provides care in intensive care and high dependency", "sop": true}]}, {"code": "COP.9", "text": "The organisation provides care in intensive care and high dependency units in a systematic manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Care of patients in intensive care and high dependency units is provided based on written guidance.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The defined admission and discharge criteria for intensive care and high dependency units are implemented.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Adequate staff and equipment are available.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Defined procedures for the situation of bed shortages are followed.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Infection prevention and control practices are followed.", "sop": true}, {"letter": "f", "category": "Achievement", "text": "The organisation shall implement a quality assurance programme.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "The organisation has a mechanism to counsel the patient and/or family periodically.", "sop": false}]}, {"code": "COP.10", "text": "Organisation provides safe obstetric care.", "elements": [{"letter": "a", "category": "Commitment", "text": "Obstetric services are organised and provided safely.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation identifies and, provides care to high-risk obstetric cases, and where needed, refers them to another appropriate centre.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Persons caring for high-risk obstetric cases are competent.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Ante-natal services are provided.", "sop": true}, {"letter": "e", "category": "Achievement", "text": "Organisation encourages and welcomes the presence of a birth companion during labour.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Organisation treats pregnant woman and her companion cordially and respectfully, ensures privacy and confidentiality for pregnant woman during her stay.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The treating doctor explains danger signs and important care activities to pregnant woman and her companion.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Obstetric patient’s assessment also includes maternal nutrition.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "Appropriate peri-natal and post-natal monitoring is performed.", "sop": false}, {"letter": "j", "category": "Commitment", "text": "The organisation caring for high-risk obstetric cases have the facilities to take care of neonates of such cases.", "sop": false}, {"letter": "k", "category": "Commitment", "text": "Organization shall adhere to legal and defined Assisted Reproductive Technology (ART) practices.", "sop": false}]}, {"code": "COP.11", "text": "Organisation provides safe paediatric services.", "elements": [{"letter": "a", "category": "Commitment", "text": "Paediatric services are organised and provided safely.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Neonatal care is in consonance with the national / international guidelines.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Those who care for children have age-specific competency.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Provisions are made for special care of children.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Paediatric assessment includes growth, developmental, immunisation and nutritional assessment.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The organisation has measures in place to prevent child / neonate abduction and abuse.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "The child’s family members are educated about nutrition, immunisation and safe parenting.", "sop": false}, {"letter": "h", "category": "Excellence", "text": "The organisation provides for adolescent friendly health care services.", "sop": false}]}, {"code": "COP.12", "text": "Procedural sedation is provided consistently and safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Procedural sedation is administered in a consistent manner.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Informed consent for administration of procedural sedation is obtained.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Competent and trained persons administer procedural sedation.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The person monitoring sedation is different from the person performing the procedure.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Intra-procedure monitoring includes at a minimum the heart rate, cardiac rhythm, respiratory rate, blood pressure, oxygen saturation, and level of sedation.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Patients are monitored after procedural sedation, and the same is documented.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Criteria are used to determine the appropriateness of discharge from the observation / recovery area.", "sop": true}, {"letter": "h", "category": "Commitment", "text": "Equipment and workforce are available to manage patients who have gone into a deeper level of sedation than initially intended.", "sop": false}]}, {"code": "COP.13", "text": "Anaesthesia services are provided in a consistent and safe manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Anaesthesia services are provided in a consistent manner.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The pre-anaesthesia assessment results in the formulation of an anaesthesia plan which is documented.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "A pre-induction assessment is performed and documented.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The anaesthesiologist obtains informed consent for administration of anaesthesia.", "sop": false}, {"letter": "e", "category": "CORE", "text": "During anaesthesia, monitoring includes a regular recording of temperature, heart rate, cardiac rhythm, respiratory rate, blood pressure, oxygen saturation and end-tidal carbon dioxide.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Patient’s post-anaesthesia status is monitored and documented.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The anaesthesiologist applies defined criteria to transfer the patient from the recovery area.", "sop": true}, {"letter": "h", "category": "Commitment", "text": "The type of anaesthesia and anaesthetic medications used are documented in the patient record.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "Procedures shall comply with infection prevention and control guidelines to prevent cross-infection between patients.", "sop": false}, {"letter": "j", "category": "Achievement", "text": "Intra-operative adverse anaesthesia events are recorded and monitored.", "sop": false}]}, {"code": "COP.14", "text": "Surgical services are provided in a consistent and safe manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Surgical services are provided in a consistent and safe manner.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Surgical patients have a pre-operative assessment, a documented pre-operative diagnosis, and pre-operative instructions are provided before surgery.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Informed consent is obtained by a surgeon before the procedure.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Care is taken to prevent adverse events like the wrong site, wrong patient and wrong surgery.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "An operative note is documented before transfer out of patient from recovery.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Post-operative care is guided by a documented plan.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Patient, personnel and material flow conform to infection prevention and control practices.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Appropriate facilities, equipment, instruments and supplies are available in the operating theatre.", "sop": false}, {"letter": "i", "category": "Achievement", "text": "The organisation shall implement a quality assurance programme.", "sop": true}, {"letter": "j", "category": "Achievement", "text": "The quality assurance programme includes surveillance of the operation theatre environment.", "sop": true}]}, {"code": "COP.15", "text": "The organ transplant programme is carried out safely.", "elements": [{"letter": "a", "category": "CORE", "text": "The organ transplant programme shall be in consonance with the legal requirements and shall be conducted ethically.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Care of transplant patients is guided by clinical practice guidelines.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation ensures education and counselling of recipient and donor through trained / qualified counsellors before organ transplantation.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation shall take measures to create awareness regarding organ donation. The organisation identifies and manages patients who are at high-risk", "sop": false}]}, {"code": "COP.16", "text": "The organisation identifies and manages patients who are at high risk of morbidity / mortality.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation identifies and manages vulnerable patients.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation identifies and manages patients who are at a risk of fall.", "sop": true}, {"letter": "c", "category": "CORE", "text": "The organisation identifies and manages patients who are at risk of developing / worsening of pressure ulcers.", "sop": true}, {"letter": "d", "category": "CORE", "text": "The organisation identifies and manages patients who are at risk of developing deep vein thrombosis.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "The organisation identifies and manages patients who need restraints.", "sop": true}]}, {"code": "COP.17", "text": "Pain management for patients is done in a consistent manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Patients in pain are effectively managed.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Patients are screened for pain.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Patients with pain undergo detailed assessment and periodic re-assessment .", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Pain alleviation measures or medications are initiated and titrated according to the patient’s need and response. Rehabilitation services are provided to the patients in a safe,", "sop": false}]}, {"code": "COP.18", "text": "Rehabilitation services are provided to the patients in a safe, collaborative and consistent manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Scope of the rehabilitation services at a minimum is commensurate to the services provided by the organisation.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Rehabilitation services are provided in a consistent manner.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Care providers collaboratively plan rehabilitation services.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "There are adequate space and equipment to provide rehabilitation.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Care is guided by functional assessment and periodic re-assessments which are done and documented.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Care is provided adhering to infection prevention and control and safety practices.", "sop": false}, {"letter": "g", "category": "Excellence", "text": "Care pathways are developed, implemented, and reviewed periodically. Nutritional therapy is provided to patients consistently and", "sop": false}]}, {"code": "COP.19", "text": "Nutritional therapy is provided to patients consistently and collaboratively.", "elements": [{"letter": "a", "category": "Commitment", "text": "Patients admitted to the organisation are screened for nutritional risk.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Nutritional assessment is done for patients found at risk during nutritional screening.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The therapeutic diet is planned and provided collaboratively.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Patients receive food according to the written order for the diet.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "When families provide food, they are educated about the patient’s diet limitations. End-of-life-care is provided in a compassionate and considerate", "sop": false}]}, {"code": "COP.20", "text": "End-of-life care is provided in a compassionate and considerate manner. This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "Commitment", "text": "End-of-life care is provided in a consistent manner in the organisation.", "sop": true}, {"letter": "b", "category": "Achievement", "text": "A multi-professional approach is used to provide end-of-life care.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "End-of-life care is in consonance with the legal requirements.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "End-of-life care also addresses the identification of the unique needs of such patient and family.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Symptomatic treatment is provided and where appropriate measures are taken for the alleviation of pain.", "sop": false}]}]}, "MOM": {"code": "MOM", "name": "Management of Medication", "standards": [{"code": "MOM.1", "text": "Pharmacy services and medication management is done safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Pharmacy services and medication management are implemented following written guidance.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "A multi-disciplinary committee guides the formulation and implementation of pharmacy services and medication management.", "sop": false}, {"letter": "c", "category": "Achievement", "text": "The multi-disciplinary committee updates medication management processes.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "There is a procedure to obtain medications when the pharmacy is closed or in case of stock outs.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "The organisation has a mechanism to inform relevant staff of key changes in pharmacy services and medication management to ensure uninterrupted and safe care. The organisation develops, updates and implements a hospital", "sop": false}]}, {"code": "MOM.2", "text": "The organisation develops, updates and implements a hospital formulary.", "elements": [{"letter": "a", "category": "CORE", "text": "A list of medications appropriate for the patients and as per the scope of the organisation’s clinical services is developed collaboratively by the multi-disciplinary committee.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The list is reviewed and updated collaboratively by the multi-disciplinary committee at least annually.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The current formulary is available for clinicians to refer to.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "The clinicians adhere to the current formulary.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation adheres to the procedure for the acquisition of formulary medications.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The organisation adheres to the procedure to obtain medications not listed in the formulary. Medications are stored appropriately and are available where", "sop": true}]}, {"code": "MOM.3", "text": "Medications are stored appropriately and are available where required.", "elements": [{"letter": "a", "category": "CORE", "text": "Medications are stored in a clean, safe and secure environment while incorporating the manufacturer’s recommendation(s).", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Sound inventory control practices guide the storage of medications throughout the organisation.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The organisation defines and updates its list of high-risk medication(s).", "sop": true}, {"letter": "d", "category": "Achievement", "text": "High-risk medications are stored in areas of the organisation where it is clinically necessary.", "sop": false}, {"letter": "e", "category": "CORE", "text": "High-risk medications including look-alike, sound-alike medications and different concentrations of the same medication are stored physically apart from each other.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The list of emergency medications is defined and is stored uniformly.", "sop": true}, {"letter": "g", "category": "CORE", "text": "Emergency medications are available all the time and are replenished promptly when used.", "sop": false}]}, {"code": "MOM.4", "text": "Medications are prescribed safely and rationally.", "elements": [{"letter": "a", "category": "Commitment", "text": "Medication prescription is in consonance with good practices / guidelines for rational prescription of medications.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation adheres to the determined minimum requirements of a prescription.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Drug allergies and previous adverse drug reactions are ascertained before prescribing.", "sop": false}, {"letter": "d", "category": "Excellence", "text": "The organisation has a mechanism to assist the clinician in prescribing appropriate medication.", "sop": false}, {"letter": "e", "category": "CORE", "text": "Reconciliation of medications occurs at transition points of patient care.", "sop": false}, {"letter": "f", "category": "CORE", "text": "Verbal orders are implemented by ensuring safe medication management practices.", "sop": true}, {"letter": "g", "category": "Achievement", "text": "Audit of medication orders / prescription is carried out to check for safe and rational prescription of medications.", "sop": false}, {"letter": "h", "category": "Achievement", "text": "Corrective and / or preventive action(s) is taken based on the audit, where appropriate.", "sop": false}]}, {"code": "MOM.5", "text": "Medication orders are written in a uniform manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation ensures that only authorised personnel write orders.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Medication orders are written in a uniform location in the medical records, which also include the patient’s name and unique identification number.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Medication orders are legible, dated, timed and signed.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Medication orders contain the name of the medicine, route of administration, strength to be administered and frequency / time of administration.", "sop": false}]}, {"code": "MOM.6", "text": "Medications are dispensed in a safe manner.", "elements": [{"letter": "a", "category": "Commitment", "text": "Dispensing of medications is done safely.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Medication recalls are handled effectively.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Near-expiry medications are handled effectively.", "sop": true}, {"letter": "d", "category": "CORE", "text": "Dispensed medications are labelled.", "sop": true}, {"letter": "e", "category": "CORE", "text": "High-risk medication orders are verified before dispensing.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Return of medications to the pharmacy is addressed.", "sop": true}]}, {"code": "MOM.7", "text": "Medications are administered safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Medications are administered by those who are permitted by law to do so.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Prepared medication is labelled before preparation of a second drug.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The patient is identified before administration.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Medication is verified from the medication order and physically inspected before administration.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Strength is verified from the order before administration.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The route is verified from the order before administration.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Timing is verified from the order before administration.", "sop": false}, {"letter": "h", "category": "CORE", "text": "Measures to avoid catheter and tubing mis-connections during medication administration are implemented.", "sop": true}, {"letter": "i", "category": "Commitment", "text": "Medication administration is documented.", "sop": false}, {"letter": "j", "category": "Commitment", "text": "Measures to govern patient’s self-administration of medications are implemented.", "sop": true}, {"letter": "k", "category": "Commitment", "text": "Measures to govern patient’s medications brought from outside the organisation shall be implemented.", "sop": true}]}, {"code": "MOM.8", "text": "Patients are monitored after medication administration. Narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals are used safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Patients shall be monitored after medication administration.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Medications shall be changed based on the monitoring where appropriate.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The organisation shall capture near misses, medication errors and adverse drug reactions.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Near misses, medication errors and adverse drug reactions shall be reported within a specified time frame.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Near misses, medication errors and adverse drug reactions are collected and analysed.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Corrective and / or preventive action(s) are taken based on the analysis. Narcotic drugs and psychotropic substances, chemotherapeutic", "sop": false}]}, {"code": "MOM.9", "text": "Narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals are used safely.", "elements": [{"letter": "a", "category": "Commitment", "text": "Narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals are used safely.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals are prescribed by appropriate caregivers.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals drugs shall be stored securely.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Chemotherapy and radio-pharmaceuticals shall be prepared properly and safely and administered by qualified personnel.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "A proper record shall be kept of the usage, administration and disposal of narcotic drugs and psychotropic substances, chemotherapeutic agents and radio-pharmaceuticals. Implantable prosthesis and medical devices shall be used in", "sop": false}]}, {"code": "MOM.10", "text": "Implantable prosthesis and medical devices are used in accordance with laid down criteria.", "elements": [{"letter": "a", "category": "Commitment", "text": "Usage of implantable prosthesis and medical devices is guided by scientific criteria for each item and national / international recognised guidelines / approvals for such specific item(s).", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation implements a mechanism for the usage of the implantable prosthesis and medical devices.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Patient and his / her family are counselled for the usage of the implantable prosthesis and medical device, including precautions if any.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The batch and the serial number of the implantable prosthesis and medical devices are recorded in the patient’s medical record, the master logbook and the discharge summary.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "Process of recall of implantable prosthesis and medical devices are handled effectively. Medical supplies and consumables are stored appropriately and are", "sop": true}]}, {"code": "MOM.11", "text": "Medical supplies and consumables are stored appropriately and are available where required. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation adheres to the defined process for the acquisition of medical supplies and consumables.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Medical supplies and consumables are used in a safe manner, where appropriate.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Medical supplies and consumables are stored in a clean, safe and secure environment; incorporating the manufacturer’s recommendation(s).", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Sound inventory control practices guide storage of medical supplies and consumables.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "There is a mechanism in place to verify the condition of medical supplies and consumables.", "sop": false}]}]}, "PRE": {"code": "PRE", "name": "Patient Rights and Education", "standards": [{"code": "PRE.1", "text": "The organisation protects and promotes patient and family rights and informs them about their responsibilities during care.", "elements": [{"letter": "a", "category": "Commitment", "text": "Patient and family rights and responsibilities are documented, displayed, and they are made aware of the same.", "sop": true}, {"letter": "b", "category": "Achievement", "text": "Patient and family rights and responsibilities are actively promoted.", "sop": true}, {"letter": "c", "category": "CORE", "text": "The organisation protects patient and family rights.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation has a mechanism to report a violation of patient and family rights.", "sop": false}, {"letter": "e", "category": "CORE", "text": "Violation of patient and family rights are monitored, analysed, and corrective / preventive action taken by the top leadership of the organisation. Patient and family rights support individual beliefs, values and", "sop": false}]}, {"code": "PRE.2", "text": "Patient and family rights support individual beliefs, values and involve the patient and family in decision-making processes.", "elements": [{"letter": "a", "category": "Commitment", "text": "Patients and family rights include respecting values and beliefs, any special preferences, cultural needs, and responding to requests for spiritual needs.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Patient and family rights include respect for personal dignity and privacy during examination, procedures and treatment.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Patient and family rights include protection from neglect or abuse.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Patient and family rights include treating patient information as confidential.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Patient and family rights include the refusal of treatment.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Patient and family rights include a right to seek an additional opinion regarding clinical care.", "sop": false}, {"letter": "g", "category": "CORE", "text": "Patient and family rights include informed consent before the transfusion of blood and blood components, anaesthesia, surgery, initiation of any research protocol and any other invasive / high-risk procedures / treatment.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Patient and family rights include a right to complain and information on how to voice a complaint.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "Patient and family rights include information on the expected cost of the treatment.", "sop": false}, {"letter": "j", "category": "Commitment", "text": "Patient and family rights include access to their clinical records.", "sop": false}, {"letter": "k", "category": "Commitment", "text": "Patient and family rights include information on the name of the treating doctor, care plan, progress and information on their health care needs.", "sop": false}, {"letter": "l", "category": "Achievement", "text": "Patient rights include determining what information regarding their care would be provided to self and family. The patient and / or family members are educated to make informed", "sop": false}]}, {"code": "PRE.3", "text": "The patient and / or family members are educated to make informed decisions and are involved in the care planning and delivery process.", "elements": [{"letter": "a", "category": "CORE", "text": "The patient and / or family members are explained about the proposed care (including the risks, benefits, alternatives), expected results and possible complications.", "sop": false}, {"letter": "b", "category": "Achievement", "text": "The care plan is prepared and modified in consultation with the patient and / or family members.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The patient and/or family members are informed about the results of diagnostic tests and the diagnosis.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The patient and/or family members are explained about any change in the patient’s condition in a timely manner.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The patient and/or family members are provided multi-disciplinary counselling when appropriate. Informed consent is obtained from the patient or family about their", "sop": false}]}, {"code": "PRE.4", "text": "Informed consent is obtained from the patient or family about their care.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation obtains informed consent from the patient or family for situations where informed consent is required.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Informed consent process adheres to statutory norms.", "sop": false}, {"letter": "c", "category": "CORE", "text": "Informed consent includes information regarding the procedure; it’s risks, benefits, alternatives and as to who will perform the procedure in a language that they can understand.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation describes who can give consent when a patient is incapable of independent decision making and implements the same.", "sop": true}, {"letter": "e", "category": "CORE", "text": "Informed consent is taken by the person performing the procedure. Patient and families have a right to information and education about", "sop": false}]}, {"code": "PRE.5", "text": "Patient and families have a right to information and education about their healthcare needs.", "elements": [{"letter": "a", "category": "CORE", "text": "Patient and / or family are educated in a language and format that they can understand.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Patient and / or family are educated about the safe and effective use of medication and the potential side effects of the medication, when appropriate.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Patient and / or family are educated about food-drug interaction.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Patient and / or family are educated about diet and nutrition.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Patient and / or family are educated about immunisations.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Patient and /or family are educated on various pain management techniques, when appropriate.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Patient and/or family are educated about their specific disease process, complications and prevention strategies.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Patient and/or family are educated about preventing healthcare associated infections.", "sop": false}, {"letter": "i", "category": "Achievement", "text": "The patients and/or family members’ special educational needs are identified and addressed.", "sop": false}, {"letter": "j", "category": "Excellence", "text": "The organisation has a mechanism to promote patient engagement to enhance clinical outcomes, safety and quality.", "sop": false}]}, {"code": "PRE.6", "text": "Patients and families have a right to information on expected costs.", "elements": [{"letter": "a", "category": "CORE", "text": "The patient and / or family members are made aware of the pricing policy in different settings (out-patient, emergency, ICU and in-patient).", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The relevant tariff list is available to patients.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The patient and/or family members are explained about the expected costs.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Patient and/or family are informed about the financial implications when there is a change in the care plan. The organisation has a mechanism to capture patient’s feedback,", "sop": false}]}, {"code": "PRE.7", "text": "The organisation has a mechanism to capture patient’s feedback and to redress complaints.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation has a mechanism to capture feedback from patients, which includes patient satisfaction.", "sop": false}, {"letter": "b", "category": "Achievement", "text": "The organisation has a mechanism to capture the patient experience.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The organisation redress patient complaints as per the defined mechanism.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Patient and / or family members are made aware of the procedure for giving feedback and / or lodging complaints.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Feedback and complaints are reviewed and / or analysed within a defined time frame.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Corrective and / or preventive action(s) are taken based on the analysis where appropriate. The organisation has a system for effective communication with", "sop": false}]}, {"code": "PRE.8", "text": "The organisation has a system for effective communication with patients and / or families. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "Commitment", "text": "Communication with the patients and / or families is done effectively.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation shall identify special situations where enhanced communication with patients and / or families would be required.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Enhanced communication with the patients and/or families is done effectively.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "The organisation ensures that there is no unacceptable communication.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The organisation has a system to monitor and review the implementation of effective communication.", "sop": false}]}]}, "IPC": {"code": "IPC", "name": "Infection Prevention and Control", "standards": [{"code": "IPC.1", "text": "The organisation has a comprehensive and coordinated Infection Prevention and Control (IPC) programme aimed at reducing / eliminating risks to patients, visitors, providers of care and community.", "elements": [{"letter": "a", "category": "CORE", "text": "The infection prevention and control programme is documented, which aims at preventing and reducing the risk of healthcare associated infections in the hospital.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The infection prevention and control programme identifies high-risk activities and has written guidance to prevent and manage infections for these activities.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The infection prevention and control programme is reviewed and updated at least once a year.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "The infection prevention and control programme is reviewed based on infection prevention and control assessment tool.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation has a multi-disciplinary infection prevention and control committee, which co-ordinates all infection prevention and control activities.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The organisation has an infection Prevention and control team, which coordinates the implementation of all infection prevention and control activities.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "The organisation has designated infection prevention and control officer as part of the infection prevention and control team.", "sop": true}, {"letter": "h", "category": "Commitment", "text": "The organisation has designated infection prevention and control nurse(s) as part of the infection prevention and control team.", "sop": true}, {"letter": "i", "category": "Commitment", "text": "The organisation implements information, education and communication programme for infection prevention and control activities for the community.", "sop": false}, {"letter": "j", "category": "Commitment", "text": "The organisation participates in managing community outbreaks. The organisation provides adequate and appropriate resources for", "sop": false}]}, {"code": "IPC.2", "text": "The organisation provides adequate and appropriate resources for infection prevention and control.", "elements": [{"letter": "a", "category": "CORE", "text": "The management makes available resources required for the infection prevention and control programme including allocation of adequate funds from its annual budget.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Adequate and appropriate personal protective equipment, soaps, and disinfectants are available and used correctly.", "sop": false}, {"letter": "c", "category": "CORE", "text": "Adequate and appropriate facilities for hand hygiene in all patient-care areas are accessible to healthcare providers.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Isolation / barrier nursing facilities are available. The organisation implements the infection prevention and control", "sop": false}]}, {"code": "IPC.3", "text": "The organisation implements the infection prevention and control processes in clinical areas.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation adheres to standard precautions at all times.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation adheres to hand-hygiene guidelines.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation adheres to transmission-based precautions.", "sop": true}, {"letter": "d", "category": "CORE", "text": "The organisation adheres to safe injection and infusion practices.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Appropriate antimicrobial usage policy is established and documented", "sop": true}, {"letter": "f", "category": "CORE", "text": "The organisation implements the antimicrobial stewardship programme and monitors the use of antimicrobial agents. The organisation implements the infection prevention and control", "sop": false}]}, {"code": "IPC.4", "text": "The organisation implements the infection prevention and control processes in support services.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation has appropriate engineering controls to prevent infections.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation designs and implements a plan to reduce the risk of infection during construction and renovation.", "sop": true}, {"letter": "c", "category": "CORE", "text": "The organisation adheres to housekeeping procedures.", "sop": true}, {"letter": "d", "category": "CORE", "text": "Biomedical waste (BMW) is handled appropriately and safely.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation adheres to laundry and linen management processes.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The organisation adheres to kitchen sanitation and food-handling issues. The organisation takes actions to prevent healthcare associated", "sop": true}]}, {"code": "IPC.5", "text": "The organisation takes actions to prevent healthcare associated Infections (HAI) in patients.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation takes action to prevent catheter-associated urinary tract Infections.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation takes action to prevent ventilator-associated pneumonia.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation takes action to prevent central line associated blood stream infections.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation takes action to prevent surgical site infections. The organisation performs surveillance to capture and monitor", "sop": false}]}, {"code": "IPC.6", "text": "The organisation performs surveillance to capture and monitor infection prevention and control data. Infection prevention measures include sterilization and / or disinfection of instruments, equipment and devices.", "elements": [{"letter": "a", "category": "CORE", "text": "The scope of surveillance incorporates tracking and analysing of infection risks, rates and trends.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Verification of data is done regularly by the infection prevention and control team.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Surveillance is directed towards the identified high-risk activities.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Surveillance includes monitoring compliance with hand-hygiene guidelines.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "Surveillance includes mechanisms to capture the occurrence of multi-drug-resistant organisms.", "sop": false}, {"letter": "f", "category": "CORE", "text": "Surveillance includes monitoring the effectiveness of housekeeping services.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Feedback regarding surveillance data is provided regularly to the appropriate health care provider.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "The organisation identifies and takes appropriate action to control outbreaks of infections.", "sop": true}, {"letter": "i", "category": "Commitment", "text": "Surveillance data is analysed and appropriate corrective and preventive actions are taken. Infection prevention measures include sterilisation and / or disinfection", "sop": false}]}, {"code": "IPC.7", "text": "Infection prevention measures include sterilization and / or disinfection of instruments, equipment and devices.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation provides adequate space and appropriate zoning for sterilisation activities.", "sop": false}, {"letter": "b", "category": "CORE", "text": "Cleaning, packing, disinfection and / or sterilisation, storing and the issue of items is done as per the written guidance.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Reprocessing of instruments, equipment and devices are done as per written guidance.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Regular validation tests for sterilisation are carried out and documented.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "The established recall procedure is implemented when a breakdown in the sterilisation system is identified.", "sop": true}, {"letter": "h", "category": "Commitment", "text": "The organisation identifies and takes appropriate action to control outbreaks The organisation takes action to prevent or reduce healthcare", "sop": false}]}, {"code": "IPC.8", "text": "The organisation takes action to prevent or reduce healthcare associated infections in its staff. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation implements occupational health and safety practices as per written guidance to reduce the risk of transmitting microorganisms among health care providers.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation implements an immunisation policy for its staff.", "sop": true}, {"letter": "c", "category": "Achievement", "text": "The organisation implements work restrictions for health care providers with transmissible infections.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation implements measures for blood and body fluid exposure prevention.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Appropriate post-exposure prophylaxis is provided to all staff members concerned.", "sop": true}]}]}, "PSQ": {"code": "PSQ", "name": "Patient Safety and Quality Improvement", "standards": [{"code": "PSQ.1", "text": "The organisation implements a structured patient safety programme. The organisation implements a structured quality improvement and continuous monitoring programme. The organisation identifies key indicators to monitor the structures, processes and outcomes, which are used as tools for continual improvement. The organisation uses appropriate quality improvement tools for its quality improvement activities.", "elements": [{"letter": "a", "category": "CORE", "text": "The patient safety programme is developed, implemented and maintained by a multi-disciplinary safety committee.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The patient safety programme is comprehensive and covers all the major elements related to patient safety.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The programme covers incidents ranging from “no harm” to “sentinel events”.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Designated patient safety officer(s) coordinates implementation of the patient safety programme.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation performs proactive analysis of patient safety risks and makes improvements accordingly.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The patient safety programme is reviewed and updated at least once a year.", "sop": false}, {"letter": "g", "category": "CORE", "text": "The organisation adapts and implements national / international patient-safety goals / solutions / framework. The organisation implements a structured quality improvement and", "sop": false}]}, {"code": "PSQ.2", "text": "The organisation implements a structured quality improvement and continuous monitoring programme.", "elements": [{"letter": "a", "category": "CORE", "text": "The quality improvement programme is developed, implemented and maintained by a multi-disciplinary committee.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The quality improvement programme is comprehensive and covers all the major elements related to quality assurance.", "sop": true}, {"letter": "c", "category": "Excellence", "text": "The quality improvement programme improves process efficiency and effectiveness.", "sop": false}, {"letter": "d", "category": "Excellence", "text": "The quality improvement programme focuses on appropriateness of clinical care.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "There is a designated individual for coordinating and implementing the quality improvement programme.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The quality improvement programme identifies opportunities for improvement based on the review at pre-defined intervals.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "The quality improvement programme is reviewed and updated at least once a year.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Audits are conducted at regular intervals as a means of continuous monitoring.", "sop": true}, {"letter": "i", "category": "CORE", "text": "There is an established process in the organisation to monitor and improve the quality of nursing care. The organisation identifies key indicators to monitor the structures,", "sop": true}]}, {"code": "PSQ.3", "text": "The organisation identifies key indicators to monitor the structures, processes and outcomes, which are used as tools for continual improvement.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation identifies and monitors key indicators to oversee the clinical structures, processes and outcomes.", "sop": false}, {"letter": "b", "category": "CORE", "text": "The organisation identifies and monitors the key indicators to oversee infection prevention and control activities.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation identifies and monitors key indicators to oversee the managerial structures, processes and outcomes.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation identifies and monitors key indicators to oversee patient safety activities.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Verification of data is done regularly by the quality team.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "There is a mechanism for analysis of data which results in identifying opportunities for improvement.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The improvements are implemented and evaluated.", "sop": false}, {"letter": "h", "category": "Achievement", "text": "Feedback about care and service is communicated to staff. The organisation uses appropriate quality improvement tools for its", "sop": false}]}, {"code": "PSQ.4", "text": "The organisation uses appropriate quality improvement tools for its quality improvement activities.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation undertakes quality improvement projects.", "sop": false}, {"letter": "b", "category": "Achievement", "text": "The Quality improvement projects shall include improvements in patient care delivery and hospital operations which will have an impact on cost and efficiency.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation uses appropriate analytical managerial and statistical tools for its quality improvement activities.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "The organisation has a mechanism to capture patient reported outcome measures.", "sop": false}]}, {"code": "PSQ.5", "text": "There is an established system for clinical audit.", "elements": [{"letter": "a", "category": "Commitment", "text": "Clinical audits are performed to improve the quality of patient care.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The parameters to be audited are defined by the organisation.", "sop": false}, {"letter": "c", "category": "Achievement", "text": "Medical and nursing staff participate in clinical audit.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Patient and staff anonymity are maintained.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Clinical audits are documented.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Remedial measures are implemented. The patient safety and quality improvement programme are supported", "sop": false}]}, {"code": "PSQ.6", "text": "The patient safety and quality improvement programme are supported by the management.", "elements": [{"letter": "a", "category": "Achievement", "text": "The management creates a culture of safety.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The leaders at all levels in the organisation are aware of the intent of the patient safety and quality improvement programme and the approach to its implementation.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Departmental leaders are involved in patient safety and quality improvement.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Organisation earmarks adequate funds from its annual budget in this regard.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The management identifies organisational performance improvement targets.", "sop": false}, {"letter": "f", "category": "Excellence", "text": "The management uses the feedback obtained from the work force to improve patient safety and quality improvement programme. Incidents are collected and analysed to ensure continual quality", "sop": false}]}, {"code": "PSQ.7", "text": "Incidents are collected and analysed to ensure continual quality improvement. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation implements an incident management system.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation has a mechanism to identify sentinel events.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation has established processes for analysis of incidents.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Corrective and preventive actions are taken based on the findings of such analysis.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The organisation incorporates risks identified in the analysis of incidents into the risk management system.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The organisation shall have a process for informing various stakeholders in case of a near miss / adverse event / sentinel event.", "sop": false}]}]}, "ROM": {"code": "ROM", "name": "Responsibility of Management", "standards": [{"code": "ROM.1", "text": "The organisation identifies those responsible for governance and their roles are defined.", "elements": [{"letter": "a", "category": "CORE", "text": "Those responsible for governance are identified and their roles and responsibilities are defined and documented.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Those responsible for governance lay down the organisation’s vision, mission and values.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Those responsible for governance approve the documented strategic and operational plans and the organisation’s annual budget.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Those responsible for governance monitor and measure the performance of the organisation against the stated mission.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Those responsible for governance appoint the senior leaders in the organisation.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Those responsible for governance support safety initiatives, clinical governance framework and quality improvement plans.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "Those responsible for governance shall develop clinical governance framework.", "sop": false}, {"letter": "h", "category": "Achievement", "text": "Those responsible for governance support the ethical management framework of the organisation.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "Those responsible for governance inform the public of the quality and performance of services. Those responsible for governance manage the organisation in an", "sop": false}]}, {"code": "ROM.2", "text": "Those responsible for governance manage the organisation in an ethical manner. Those responsible for governance ensure sustainability in hospital by addressing environmental, social and economic factors from long term well-being of healthcare system and community. The organisation is headed by a leader who shall be responsible for operating the organisation on a day-to-day basis.", "elements": [{"letter": "a", "category": "CORE", "text": "The leaders establish the organisation’s ethical management framework.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The ethical management framework includes processes for managing issues with ethical implications, dilemmas and concerns.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation discloses its ownership.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation honestly portrays its affiliations and accreditations. Those responsible for governance ensure sustainability in hospitals by", "sop": false}]}, {"code": "ROM.3", "text": "New Standard added to address environmental, social and economic factors from long term well being of healthcare system and community.", "elements": [{"letter": "a", "category": "Commitment", "text": "Those responsible for governance address the organisation’s sustainability programme in terms of Environment Social and Governance (ESG) responsibility.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation takes initiatives towards an energy-efficient and environmentally friendly hospital.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Those responsible for governance address the organisations social responsibility.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Staff well-being is promoted.", "sop": false}, {"letter": "e", "category": "Excellence", "text": "The organisation follows sustainable procurement practices.", "sop": false}, {"letter": "f", "category": "Achievement", "text": "Hospitals shall encourage employees to use common / public transportation to reduce the environmental impact of commuting and carbon footprint.", "sop": false}, {"letter": "g", "category": "Achievement", "text": "The organisation ensures financial sustainability of the hospital by balancing the financial aspects of healthcare delivery. The organisation is headed by a leader who shall be responsible", "sop": false}]}, {"code": "ROM.4", "text": "The organisation is headed by a leader who shall be responsible for operating the organisation on a day-to-day basis.", "elements": [{"letter": "a", "category": "Commitment", "text": "The person heading the organisation has requisite and appropriate administrative qualifications and experience.", "sop": false}, {"letter": "b", "category": "CORE", "text": "The leader is responsible for and complies with the laid-down and applicable legislations, regulations and notifications.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The leader appoints / participates in the recruitment of department leaders of the organisation who will assist in the day-to-day functioning of the organisation.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "The leader ensures that each organisational programme, service, site or department has effective leadership.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "The performance of the organisation’s leader is reviewed for effectiveness.", "sop": false}]}, {"code": "ROM.5", "text": "The organisation displays professionalism in its functioning. Management ensures that patient-safety aspects and risk-management issues are an integral part of patient care and hospital management. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation has strategic and operational plans, including long-term and short-term goals commensurate to the organisation’s vision, mission and values in consultation with the various stakeholders.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation coordinates the functioning with departments and external agencies and monitors the progress in achieving the defined goals and objectives.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation plans and budgets for its activities annually.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "The functioning of committees is reviewed for their effectiveness.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation documents the service standards that are measurable and monitors them.", "sop": true}, {"letter": "f", "category": "Excellence", "text": "Systems and processes are in place for change management. Leadership ensures that patient-safety aspects and risk-management", "sop": true}]}, {"code": "ROM.6", "text": "Management ensures that patient-safety aspects and risk-management issues are an integral part of patient care and hospital management.", "elements": [{"letter": "a", "category": "CORE", "text": "Leadership ensures proactive risk management across the organisation.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Leadership provides resources for proactive risk-assessment and risk-reduction activities.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Leadership ensures integration between quality improvement, risk-management and strategic planning within the organisation.", "sop": false}, {"letter": "d", "category": "Achievement", "text": "Leadership ensures implementation of systems for internal and external reporting of system and process failures.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Leadership ensures that it has a documented agreement for all outsourced services that include service parameters.", "sop": false}, {"letter": "f", "category": "Achievement", "text": "Leadership monitors the quality of the outsourced services and improvements are made as required.", "sop": false}]}]}, "FMS": {"code": "FMS", "name": "Facility Management and Safety", "standards": [{"code": "FMS.1", "text": "The organisation has a system in place to provide a safe and secure environment. The organisation’s environment and facilities operate in a planned manner and promotes environment-friendly measures. The organisation’s environment and facilities operate to ensure the safety of patients, their families, staff and visitors.", "elements": [{"letter": "a", "category": "CORE", "text": "Patient safety devices and infrastructure are installed across the organisation and inspected periodically.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The organisation has facilities for the differently-abled.", "sop": false}, {"letter": "c", "category": "CORE", "text": "Facility inspection rounds to ensure safety are conducted at least once a month.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Inspection reports of facility rounds are documented and corrective and preventive measures are undertaken.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Before construction, renovation and expansion of the existing hospital, risk-assessment is carried out. The organisation’s environment and facilities operate in a planned", "sop": false}]}, {"code": "FMS.2", "text": "The organisation’s environment and facilities operate in a planned manner and promotes environment-friendly measures.", "elements": [{"letter": "a", "category": "Commitment", "text": "Facilities and space provisions are appropriate to the scope of services.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "As built and updated drawings are maintained as per statutory requirements.", "sop": false}, {"letter": "c", "category": "CORE", "text": "There are internal and external sign postings in the organisation in a manner understood by the patient, families and community.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Potable water and electricity are available round the clock.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Alternate sources for electricity and water are provided as a backup for any failure / shortage.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The organisation tests the functioning of these alternate sources at a predefined frequency. The organisation’s environment and facilities operate to ensure", "sop": false}]}, {"code": "FMS.3", "text": "The organisation’s environment and facilities operate to ensure the safety of patients, their families, staff and visitors.", "elements": [{"letter": "a", "category": "Commitment", "text": "Operational planning identifies areas which need to have extra security and describes access to different areas in the hospital by staff, patients, and visitors.", "sop": true}, {"letter": "b", "category": "Excellence", "text": "Patient safety aspects in terms of structural safety of hospitals, especially of critical areas are considered while planning, design and construction of new hospitals and re-planning, assessment and retrofitting of existing hospitals.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation conducts electrical safety audits for the facility.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "There is a procedure which addresses the identification and disposal of material(s) not in use in the organisation.", "sop": true}, {"letter": "e", "category": "CORE", "text": "Hazardous materials are identified and used safely within the organisation.", "sop": true}, {"letter": "f", "category": "Commitment", "text": "The plan for managing spills of hazardous materials is implemented. The organisation has a programme for the facility, engineering support", "sop": true}]}, {"code": "FMS.4", "text": "The organisation has a programme for the facility, engineering support services and utility system.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation plans for utility and engineering equipment in accordance with its services and strategic plan.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Equipment is inventoried, and proper logs are maintained as required.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The documented operational and maintenance (preventive and breakdown) plan is implemented.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Utility equipment, are periodically inspected and calibrated (wherever applicable) for their proper functioning.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Competent personnel operate, inspect, test and maintain equipment and utility systems.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Maintenance staff is contactable round the clock for emergency repairs.", "sop": false}, {"letter": "g", "category": "Achievement", "text": "Downtime for critical equipment breakdowns is monitored from reporting to inspection and implementation of corrective actions.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Written guidance supports equipment replacement, identification of unwanted material and disposal. The organisation has a programme for medical equipment", "sop": true}]}, {"code": "FMS.5", "text": "The organisation has a programme for medical equipment management.", "elements": [{"letter": "a", "category": "Commitment", "text": "The organisation plans for medical equipment in accordance with its services and strategic plan.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Medical equipment is inventoried and proper logs are maintained as required.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The documented operational and maintenance (preventive and breakdown) plan for medical equipment is implemented.", "sop": true}, {"letter": "d", "category": "Commitment", "text": "Medical equipment is periodically inspected and calibrated for their proper functioning.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Qualified and trained personnel operate and maintain medical equipment.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Written guidance supports medical equipment replacement and disposal.", "sop": true}, {"letter": "g", "category": "Commitment", "text": "There is monitoring of medical equipment and medical devices related to adverse events, and compliance hazard notices on recalls.", "sop": true}, {"letter": "h", "category": "Achievement", "text": "Downtime for critical equipment breakdown is monitored from reporting to inspection and implementation of corrective actions. The organisation has a programme for medical gases, vacuum and", "sop": false}]}, {"code": "FMS.6", "text": "The organisation has a programme for medical gases, vacuum and compressed air.", "elements": [{"letter": "a", "category": "Commitment", "text": "Written guidance governs the implementation of procurement, handling, storage, distribution, usage and replenishment of medical gases.", "sop": true}, {"letter": "b", "category": "CORE", "text": "Medical gases are handled, stored, distributed and used in a safe manner.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "There is an operational, inspection, testing and maintenance plan for piped medical gas, compressed air and vacuum installation.", "sop": true}, {"letter": "d", "category": "CORE", "text": "Alternate sources for medical gases, vacuum and compressed air are provided for, in case of failure.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation regularly tests the functioning of these alternate sources. The organisation has plans for fire and non-fire emergencies within", "sop": false}]}, {"code": "FMS.7", "text": "The organisation has plans for fire and non-fire emergencies within the facilities. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation has plans and provisions for early detection, abatement, containment of fire and evacuation in the event of fire emergencies.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation has plans and provisions for identification, and management of non-fire emergencies.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The organisation has a documented and displayed exit plan in case of fire and non-fire emergencies.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Mock drills are held at least twice a year.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "There is a maintenance plan for fire-related equipment and infrastructure", "sop": true}]}]}, "HRM": {"code": "HRM", "name": "Human Resource Management", "standards": [{"code": "HRM.1", "text": "The organisation has a documented system of human resource planning.", "elements": [{"letter": "a", "category": "Commitment", "text": "Human resource planning supports the organisation’s current and future ability to meet the care, treatment and service needs of the patient.", "sop": false}, {"letter": "b", "category": "CORE", "text": "The organisation maintains an adequate number and mix of staff to meet the care, treatment and service needs of the patient.", "sop": true}, {"letter": "c", "category": "Achievement", "text": "The organisation has contingency plans to manage long and short-term workforce shortages, including unplanned shortages.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The job specification and job description are defined for each category of staff.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation performs a background check of new staff.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Reporting relationships are defined for each category of staff.", "sop": true}, {"letter": "g", "category": "Achievement", "text": "Exit interviews are conducted and used as a tool to improve human resource practices.", "sop": false}]}, {"code": "HRM.2", "text": "The organisation implements a defined process for staff recruitment.", "elements": [{"letter": "a", "category": "CORE", "text": "Written guidance governs the process of recruitment.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "A pre-employment medical examination is conducted on the staff.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The organisation defines and implements a code of conduct for its staff.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Administrative procedures for human resource management are documented. Staff are provided induction training at the time of joining the", "sop": true}]}, {"code": "HRM.3", "text": "Staff are provided induction training at the time of joining the organisation.", "elements": [{"letter": "a", "category": "CORE", "text": "Staff are provided with induction training.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The induction training includes orientation to the organisation’s vision, mission and values.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The induction training includes awareness on staff rights and responsibilities and patient rights and responsibilities.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The induction training includes training on safety.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The induction training includes training on cardio-pulmonary resuscitation for staff.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The induction training includes training in hospital infection prevention and control.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The induction training includes orientation to the service standards of the organisation.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "The induction training includes an orientation on administrative procedures.", "sop": false}, {"letter": "i", "category": "Commitment", "text": "The induction training includes an orientation on relevant department / unit / service / programme’s policies and procedures.", "sop": false}, {"letter": "j", "category": "Commitment", "text": "Staff is trained on information systems, information security, information use and management. There is an on-going programme for professional training and", "sop": false}]}, {"code": "HRM.4", "text": "There is an on-going programme for professional training and development of the staff.", "elements": [{"letter": "a", "category": "CORE", "text": "Written guidance governs training and development policy for the staff.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The organisation maintains the training record.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Training also occurs when job responsibilities change/new equipment is introduced.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Feedback mechanisms are in place for improvement of training and development programme.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "Evaluation of training effectiveness is done by the organisation.", "sop": false}, {"letter": "f", "category": "Achievement", "text": "The organisation supports continuing professional development and learning.", "sop": false}]}, {"code": "HRM.5", "text": "Staff are appropriately trained based on their specific job description.", "elements": [{"letter": "a", "category": "Commitment", "text": "Staff involved in blood transfusion services are trained in the handling of blood and blood products.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Staff are trained in handling vulnerable patients.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Staff are trained in control and restraint techniques.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Staff are trained in healthcare communication techniques.", "sop": false}, {"letter": "e", "category": "CORE", "text": "Staff involved in direct patient care are provided training on cardio-pulmonary resuscitation periodically.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Staff are provided training on infection prevention and control.", "sop": false}]}, {"code": "HRM.6", "text": "Staff are trained in safety and quality-related aspects. *This implies that the objective element requires documentation. An appraisal system for evaluating the performance of staff exists as an integral part of the human resource management process.", "elements": [{"letter": "a", "category": "Commitment", "text": "Staff are trained in the organisation’s safety programme.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Staff are provided training in the detection, handling, minimisation and elimination of identified risks within the organisation’s environment.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Staff members are made aware of procedures to follow in the event of an incident.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Staff are trained in occupational safety aspects.", "sop": false}, {"letter": "e", "category": "CORE", "text": "Staff are trained in the organisation’s disaster management plan.", "sop": false}, {"letter": "f", "category": "CORE", "text": "Staff are trained in handling fire and non-fire emergencies.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Staff are trained in the organisation’s quality improvement programme. An appraisal system for evaluating the performance of staff exists", "sop": false}]}, {"code": "HRM.7", "text": "An appraisal system for evaluating the performance of staff exists as an integral part of the human resource management process.", "elements": [{"letter": "a", "category": "Commitment", "text": "Performance appraisal is done for staff within the organisation.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The staff are made aware of the system of appraisal at the time of induction.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Performance is evaluated based on the pre-determined criteria.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The appraisal system is used as a tool for further development.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Performance appraisal is carried out at defined intervals and is documented. Process for disciplinary and grievance handling is defined and", "sop": false}]}, {"code": "HRM.8", "text": "Process for disciplinary and grievance handling is defined and implemented in the organisation.", "elements": [{"letter": "a", "category": "Commitment", "text": "Written guidance governs disciplinary and grievance handling mechanisms.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "The disciplinary and grievance handling mechanism is known to all categories of staff of the organisation.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The disciplinary policy and procedure are based on the principles of natural justice.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The disciplinary and grievance procedure is in consonance with the prevailing laws.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "There is a provision for appeals in all disciplinary cases.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Actions are taken to redress the grievance.", "sop": false}]}, {"code": "HRM.9", "text": "The organisation addresses their health and safety needs of the staff.", "elements": [{"letter": "a", "category": "Commitment", "text": "Health problems of the staff, including occupational health hazards, are taken care of in accordance with the organisation’s policy.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Health checks of staff dealing with direct patient care are done at least once a year and the findings / results are documented.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Organisation provides treatment to staff who sustain workplace-related injuries.", "sop": false}, {"letter": "d", "category": "CORE", "text": "The organisation has measures in place for prevention and handling workplace violence.", "sop": true}]}, {"code": "HRM.10", "text": "There is documented personal information for each staff member. There is a process for credentialing and privileging of medical professionals, permitted to provide patient care without supervision. There is a process for credentialing and privileging of nursing professionals, permitted to provide patient care without supervision. There is a process for credentialing and privileging of para-clinical professionals, permitted to provide patient care without supervision.", "elements": [{"letter": "a", "category": "Commitment", "text": "Personal files are maintained with respect to all staff, and their confidentiality is ensured.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The personal files contain personal information regarding the staff’s qualification, job description, verification of credentials and health status.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "Records of in-service training and education are maintained.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Personal files contain results of all evaluations and remarks. There is a process for credentialing and privileging of medical", "sop": false}]}, {"code": "HRM.11", "text": "There is a process for credentialing and privileging of medical professionals, permitted to provide patient care without supervision.", "elements": [{"letter": "a", "category": "CORE", "text": "Medical professionals permitted by law, regulation and the organisation provide patient care without supervision are identified.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The education, registration, training and experience of the identified medical professionals are documented and updated periodically.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The information about medical professionals is appropriately verified when possible.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Medical professionals are granted privileges to admit and care for patients in consonance with their qualification, training, experience and registration.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The requisite services to be provided by the medical professionals are known to them as well as the various departments / units of the organisation.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Medical professionals admit and care for patients as per their privileging. There is a process for credentialing and privileging of nursing", "sop": false}]}, {"code": "HRM.12", "text": "There is a process for credentialing and privileging of nursing professionals, permitted to provide patient care without supervision.", "elements": [{"letter": "a", "category": "CORE", "text": "Nursing staff permitted by law, regulation and the organisation to provide patient care without supervision are identified.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The education, registration, training and experience of nursing staff are documented and updated periodically.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The information about the nursing staff is appropriately verified when possible.", "sop": false}, {"letter": "d", "category": "CORE", "text": "Nursing staff are granted privileges in consonance with their qualification, training, experience and registration.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The requisite services to be provided by the nursing staff are known to them as well as the concerned departments / units of the organisation.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Nursing professionals care for patients as per their privileging. There is a process for credentialing and privileging of para-clinical", "sop": false}]}, {"code": "HRM.13", "text": "There is a process for credentialing and privileging of para-clinical professionals, permitted to provide patient care without supervision.", "elements": [{"letter": "a", "category": "CORE", "text": "Para-clinical professionals permitted by law, regulation and the organisation to provide patient care without supervision are identified.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The education, registration, training and experience of para-clinical professionals are appropriately verified, documented and updated periodically.", "sop": false}, {"letter": "c", "category": "CORE", "text": "Para-clinical professionals are granted privileges in consonance with their qualification, training, experience and registration.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The requisite services to be provided by the para-clinical professionals are known to them as well as the concerned departments/units of the organisation.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "Para-clinical professionals care for patients as per their privileging.", "sop": false}]}]}, "IMS": {"code": "IMS", "name": "Information Management System", "standards": [{"code": "IMS.1", "text": "Information needs of the patients, visitors, staff, management and external agencies are met.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation identifies the information needs of the patients, visitors, staff, management, external agencies and community.", "sop": true}, {"letter": "b", "category": "Commitment", "text": "Identified information needs are captured and/or disseminated.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "Information management and technology acquisitions are commensurate with the identified information needs.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "A maintenance plan for information technology and communication network is implemented.", "sop": false}, {"letter": "e", "category": "Achievement", "text": "Contingency plan ensures continuity of information capture, integration and dissemination.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The organisation ensures that information resources are accurate and meet stakeholder requirements.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The organisation contributes to external databases in accordance with the law and regulations.", "sop": false}, {"letter": "h", "category": "Excellence", "text": "The organisation shall make efforts to use digital health technology to improve operational efficiency, patient safety and patient experience. The organisation has processes in place for management and control", "sop": false}]}, {"code": "IMS.2", "text": "The organisation has processes in place for management and control of data and information.", "elements": [{"letter": "a", "category": "Commitment", "text": "Processes for data collection are standardised.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "Data is analysed to meet the information needs.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The organisation disseminates the information in a timely and accurate manner.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The organisation stores and retrieves data according to its information needs.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Clinical and managerial staff participate in selecting, integrating and using data for meeting the information needs. The patients cared for by the organisation have a complete and", "sop": false}]}, {"code": "IMS.3", "text": "The patients cared for by the organisation have a complete and accurate medical record.", "elements": [{"letter": "a", "category": "CORE", "text": "A unique identifier is assigned to the medical record.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The contents of the medical record are identified and documented.", "sop": true}, {"letter": "c", "category": "CORE", "text": "The medical record provides a complete, up-to-date and chronological account of patient care.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Authorised staff make the entries in the medical record.", "sop": true}, {"letter": "e", "category": "Commitment", "text": "Entry in the medical record is signed, dated and timed.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The author of the entry can be identified.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "The medical record has only authorised abbreviations.", "sop": false}]}, {"code": "IMS.4", "text": "The medical record reflects the continuity of care.", "elements": [{"letter": "a", "category": "Commitment", "text": "The medical record contains information regarding reasons for admission, diagnosis and care plan.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The medical record contains the details of assessments, re-assessments and consultations.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The medical record contains the results of investigations and the details of the care provided.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "Operative and other procedures performed are incorporated in the medical record.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "When a patient is transferred to another organisation, the medical record shall contain the details of the transfer.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The medical record contains a signed copy of the discharge summary.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "In case of death, the medical record contains a copy of the medical certificate of the cause of death.", "sop": false}, {"letter": "h", "category": "Commitment", "text": "Care providers have access to current and past medical record. The organisation maintains confidentiality, integrity and security of", "sop": false}]}, {"code": "IMS.5", "text": "The organisation maintain confidentiality, integrity and security of records, data and information. The organisation ensures availability of current and relevant documents, records, data and information and provide for retention of the same.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation maintains the confidentiality of records, data and information.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation maintains the integrity of records, data and information.", "sop": false}, {"letter": "c", "category": "CORE", "text": "The organisation maintains the security of records, data and information.", "sop": true}, {"letter": "d", "category": "Achievement", "text": "The organisation uses developments in appropriate technology for improving confidentiality, integrity and security.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The organisation discloses privileged health information as authorised by the patient and / or as required by law.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "Request for access to information in the medical records by patients / physicians and other public agencies are addressed consistently. The organisation ensures availability of current and relevant documents,", "sop": true}]}, {"code": "IMS.6", "text": "The organisation ensures availability of current and relevant documents, records, data and information and provide for retention of the same.", "elements": [{"letter": "a", "category": "CORE", "text": "The organisation has an effective process for document control.", "sop": true}, {"letter": "b", "category": "CORE", "text": "The organisation retains patient’s clinical records, data and information according to its requirements.", "sop": true}, {"letter": "c", "category": "Commitment", "text": "The retention process provides expected confidentiality and security.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The destruction of medical records, data and information are in accordance with the written guidance.", "sop": true}]}, {"code": "IMS.7", "text": "The organisation carries out a review of medical records. *This implies that the objective element requires documentation.", "elements": [{"letter": "a", "category": "CORE", "text": "The medical records are reviewed periodically.", "sop": false}, {"letter": "b", "category": "Commitment", "text": "The review uses a representative sample based on statistical principles.", "sop": false}, {"letter": "c", "category": "Commitment", "text": "The review is conducted by identified individuals.", "sop": false}, {"letter": "d", "category": "Commitment", "text": "The review of records is based on identified parameters.", "sop": false}, {"letter": "e", "category": "Commitment", "text": "The review process includes records of both active and discharged patients.", "sop": false}, {"letter": "f", "category": "Commitment", "text": "The review points out and documents any deficiencies in records.", "sop": false}, {"letter": "g", "category": "Commitment", "text": "Appropriate corrective and preventive measures are undertaken.", "sop": true}]}]}}, "official": {"AAC": {"standards": 13, "elements": 87, "core": 6, "commitment": 68, "achievement": 9, "excellence": 4}, "COP": {"standards": 20, "elements": 135, "core": 13, "commitment": 107, "achievement": 12, "excellence": 4}, "MOM": {"standards": 11, "elements": 68, "core": 13, "commitment": 48, "achievement": 6, "excellence": 1}, "PRE": {"standards": 8, "elements": 52, "core": 12, "commitment": 32, "achievement": 7, "excellence": 1}, "IPC": {"standards": 8, "elements": 49, "core": 13, "commitment": 33, "achievement": 3, "excellence": 0}, "PSQ": {"standards": 7, "elements": 46, "core": 8, "commitment": 28, "achievement": 7, "excellence": 3}, "ROM": {"standards": 6, "elements": 37, "core": 4, "commitment": 23, "achievement": 8, "excellence": 2}, "FMS": {"standards": 7, "elements": 43, "core": 11, "commitment": 29, "achievement": 2, "excellence": 1}, "HRM": {"standards": 13, "elements": 76, "core": 16, "commitment": 56, "achievement": 4, "excellence": 0}, "IMS": {"standards": 7, "elements": 45, "core": 9, "commitment": 33, "achievement": 2, "excellence": 1}}, "totals": {"standards": 100, "elements": 639, "core": 105, "commitment": 457, "achievement": 60, "excellence": 17}};